const graph = { A: ["B", "C"], B: ["D"], C: ["D"], D: [] };
const start = require("fs").readFileSync(0, "utf8").trim();
const visited = new Set([start]);
const queue = [start];
while (queue.length > 0) {
  const node = queue.shift();
  console.log(node);
  for (const next of graph[node]) {
    if (!visited.has(next)) {
      visited.add(next);
      queue.push(next);
    }
  }
}

