graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
start = input()
visited = {start}
queue = [start]
while len(queue) > 0:
    node = queue.pop(0)
    print(node)
    for next_node in graph[node]:
        if next_node not in visited:
            visited.add(next_node)
            queue.append(next_node)
